/* Authority is a NUL-terminated URI authority; numeric fields retain wire widths. */
typedef struct NXD_UPROTOCOL_URI_STRUCT
{
    CHAR authority[ NXD_UPROTOCOL_AUTHORITY_MAX + 1u ];
    uint32_t ue_id;
    UINT version;
    UINT resource;
} NXD_UPROTOCOL_URI;

/* UUIDv7 in network byte order; the first six bytes contain epoch milliseconds. */
typedef struct NXD_UPROTOCOL_UUID_STRUCT
{
    UCHAR bytes[16];
} NXD_UPROTOCOL_UUID;

/* Optional scalar presence is explicit, including values equal to zero.
   Payload memory is borrowed for the duration of send or listener delivery. */
typedef struct NXD_UPROTOCOL_MESSAGE_STRUCT
{
    NXD_UPROTOCOL_UUID id;
    UINT type;
    NXD_UPROTOCOL_URI source;
    NXD_UPROTOCOL_URI sink;
    UINT present;
    UINT priority;
    uint32_t ttl;
    uint32_t permission_level;
    UINT commstatus;
    NXD_UPROTOCOL_UUID reqid;
    CHAR token[NXD_UPROTOCOL_TOKEN_SIZE];
    CHAR traceparent[NXD_UPROTOCOL_TRACE_SIZE];
    UINT payload_format;
    const UCHAR *payload;
    UINT payload_length;
} NXD_UPROTOCOL_MESSAGE;

typedef VOID (*NXD_UPROTOCOL_LISTENER)(const NXD_UPROTOCOL_MESSAGE *message, VOID *context);
typedef uint64_t (*NXD_UPROTOCOL_CLOCK)(VOID *context);

/* Connection and identity configuration. Clock must return Unix milliseconds.
   MQTT login/certificates are configured on the MQTT client before connecting. */
typedef struct NXD_UPROTOCOL_CONFIG_STRUCT
{
    NXD_UPROTOCOL_URI local_uri;
    UINT mode;
    NXD_ADDRESS server;
    UINT port;
    UINT keepalive;
    UINT clean_start;
    ULONG session_expiry;
    ULONG maximum_packet_size;
    NXD_UPROTOCOL_CLOCK clock;
    VOID *clock_context;
#ifdef NX_SECURE_ENABLE
    UINT (*tls_setup)(NXD_MQTT_CLIENT *, NX_SECURE_TLS_SESSION *, NX_SECURE_X509_CERT *, NX_SECURE_X509_CERT *);
#endif
} NXD_UPROTOCOL_CONFIG;

/* One listener registration and the MQTT subscription it shares with peers. */
typedef struct NXD_UPROTOCOL_REGISTRATION_STRUCT
{
    UINT active;
    UINT has_sink;
    NXD_UPROTOCOL_URI source;
    NXD_UPROTOCOL_URI sink;
    CHAR topic[NXD_UPROTOCOL_TOPIC_SIZE];
    NXD_UPROTOCOL_LISTENER listener;
    VOID *context;
} NXD_UPROTOCOL_REGISTRATION;

/* Application-owned transport, with no heap allocation or private worker thread.
   Call process periodically from an application ThreadX thread. Callbacks run on
   that thread; callback data remains valid only until the callback returns. */
typedef struct NXD_UPROTOCOL_CLIENT_STRUCT
{
    NXD_MQTT_CLIENT *mqtt;
    NXD_UPROTOCOL_CONFIG config;
    TX_MUTEX mutex;
    TX_EVENT_FLAGS_GROUP ack_events;
    volatile USHORT ack_id;
    volatile UINT ack_type;
    volatile UINT ack_reason;
    UINT started;
    UINT connected;
    UINT dispatching;
    ULONG retry_at;
    ULONG retry_delay;
    UINT last_mqtt_status;
    NXD_UPROTOCOL_REGISTRATION listeners[NXD_UPROTOCOL_MAX_LISTENERS];
    UCHAR properties[NXD_UPROTOCOL_PROPERTIES_SIZE];
    CHAR topic[NXD_UPROTOCOL_TOPIC_SIZE];
    NXD_UPROTOCOL_MESSAGE incoming;
} NXD_UPROTOCOL_CLIENT;

